package constants;

/**
 * 4 loai task co dinh cua de bai: Code, Test, Design, Review.
 *
 * @author CuongThai Academy
 */
public enum TaskType {

    // Loai 1: viet code
    CODE(1, "Code"),

    // Loai 2: kiem thu
    TEST(2, "Test"),

    // Loai 3: thiet ke
    DESIGN(3, "Design"),

    // Loai 4: review
    REVIEW(4, "Review");

    // Ma loai task (1 den 4)
    private int id;

    // Ten loai task in ra bang
    private String name;

    // Tao 1 loai task voi ma va ten
    private TaskType(int id, String name) {
        this.id = id;
        this.name = name;
    }

    // Tim loai task theo ma; Main da kiem ma tu 1 den 4 nen luon tim thay
    public static TaskType getTaskTypeById(int taskTypeId) {
        TaskType result = null;

        // Duyet tung loai task de so ma
        for (TaskType taskType : TaskType.values()) {
            // Trung ma thi giu lai loai task do
            if (taskType.getId() == taskTypeId) {
                result = taskType;
            }
        }

        return result;
    }

    // Tra ve ma loai task
    public int getId() {
        return id;
    }

    // Tra ve ten loai task
    public String getName() {
        return name;
    }
}

