package main;

import constants.Constants;
import constants.Message;
import constants.TaskType;
import controller.TaskController;
import dto.TaskDTO;
import java.util.Date;
import java.util.Scanner;
import utils.Validation;

/**
 * Diem bat dau: menu, ban phim (Scanner chi o day), kiem tung o qua Validation, goi
 * Controller dung 1 lan cho moi lua chon.
 *
 * @author CuongThai Academy
 */
public final class Main {

    // Constructor private: Main chi co ham static (checklist 3.4)
    private Main() {
    }

    // Chay chuong trinh: lap menu den khi chon 4
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        TaskController taskController = new TaskController();
        TaskDTO taskDTO = null;
        boolean isRunning = true;

        // Hien lai menu sau moi chuc nang, den khi chon thoat (khong dung System.exit)
        while (isRunning) {
            System.out.println(Message.MENU_HEADER.concat(Message.MENU_BODY));

            // Moi lua chon goi controller dung 1 lan
            switch (getMenuChoice(scanner)) {
                // 1: nhap va kiem du 7 o roi them task
                case Constants.MENU_ADD:
                    System.out.println(Message.TITLE_ADD);
                    taskDTO = inputTaskData(scanner);
                    taskController.addTask(taskDTO);
                    break;

                // 2: nhap va kiem ID roi xoa task (kho tu kiem ID co hay khong)
                case Constants.MENU_DELETE:
                    System.out.println(Message.TITLE_DELETE);
                    taskDTO = new TaskDTO();
                    taskDTO.setId(getTaskId(scanner));
                    taskController.deleteTask(taskDTO);
                    break;

                // 3: hien thi bang task
                case Constants.MENU_DISPLAY:
                    taskController.displayTasks();
                    break;

                // 4: tat co de thoat vong lap
                case Constants.MENU_EXIT:
                    isRunning = false;
                    break;

                // Khong xay ra: getMenuChoice chi tra ve 1 den 4
                default:
                    break;
            }
        }
    }

    // Nhap va kiem du thong tin 1 task, gom vao 1 phieu DTO moi
    private static TaskDTO inputTaskData(Scanner scanner) {
        TaskDTO taskDTO = new TaskDTO();
        double planFrom = 0;

        taskDTO.setRequirementName(getRequirementName(scanner));
        taskDTO.setTaskType(TaskType.getTaskTypeById(getTaskTypeChoice(scanner)));
        taskDTO.setDate(getDate(scanner));

        // Gio bat dau toi da 17.0 de con cho cho gio ket thuc; To phai lon hon From
        planFrom = getPlanFrom(scanner);
        taskDTO.setPlanFrom(planFrom);
        taskDTO.setPlanTo(getPlanTo(scanner, planFrom));

        // Nguoi lam va nguoi review cung 1 luat ten
        taskDTO.setAssign(getPersonName(scanner, Message.INPUT_ASSIGNEE));
        taskDTO.setReviewer(getPersonName(scanner, Message.INPUT_REVIEWER));

        return taskDTO;
    }

    // Hoi lua chon menu (1 den 4) den khi dung
    private static int getMenuChoice(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_CHOICE);
                return Validation.getInt(scanner.nextLine(), Constants.MENU_MIN,
                        Constants.MENU_EXIT);
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi loai task (1 den 4) den khi dung
    private static int getTaskTypeChoice(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In bang loai task + cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_TASK_TYPE_CHOICE);
                return Validation.getInt(scanner.nextLine(), Constants.TASK_TYPE_MIN,
                        Constants.TASK_TYPE_MAX);
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ID task can xoa (so nguyen tu 1 tro len) den khi dung
    private static int getTaskId(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_TASK_ID);
                return Validation.getTaskId(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ten requirement den khi khong rong
    private static String getRequirementName(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_REQUIREMENT_NAME);
                return Validation.getRequirementName(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ten nguoi (Assignee hoac Reviewer, cau nhac truyen vao) den khi dung dinh dang
    private static String getPersonName(Scanner scanner, String prompt) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(prompt);
                return Validation.getPersonName(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi ngay dd-MM-yyyy den khi la ngay co that
    private static Date getDate(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_DATE);
                return Validation.getDate(scanner.nextLine());
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi gio bat dau: 8.0 den 17.0, buoc 0.5
    private static double getPlanFrom(Scanner scanner) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem (chua lai 0.5 cho gio ket thuc)
            try {
                System.out.print(Message.INPUT_PLAN_FROM);
                return Validation.getDouble(scanner.nextLine(), Constants.PLAN_MIN,
                        Constants.PLAN_MAX - Constants.PLAN_STEP);
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }

    // Hoi gio ket thuc: lon hon gio bat dau it nhat 0.5, toi da 17.5
    private static double getPlanTo(Scanner scanner, double planFrom) {
        // Lap den khi Validation chap nhan
        while (true) {
            // In cau nhac, doc dong va kiem
            try {
                System.out.print(Message.INPUT_PLAN_TO);
                return Validation.getDouble(scanner.nextLine(), planFrom + Constants.PLAN_STEP,
                        Constants.PLAN_MAX);
            } catch (Exception e) {
                // Sai thi in cau bao loi roi hoi lai
                System.out.println(e.getMessage());
            }
        }
    }
}

