package repository;

import constants.Message;
import dto.ResponseDTO;
import dto.TaskDTO;
import java.util.ArrayList;
import java.util.List;
import model.Task;

/**
 * Kho giu danh sach task trong bo nho: them, xoa (tu kiem ID co hay khong), lay bang task.
 *
 * @author CuongThai Academy
 */
public class TaskRepository {

    // Danh sach task dang co, tang dan theo ID
    private List<Task> taskList;

    // ID cua task them gan nhat (de: ID = ID last task + 1)
    private int lastId;

    // Constructor: kho rong, chua co task nao
    public TaskRepository() {
        taskList = new ArrayList<>();
        lastId = 0;
    }

    // Them task moi tu phieu DTO, tra ve ID vua cap (ham addTask cua de)
    public int addTask(TaskDTO taskDTO) {
        Task task = new Task(taskDTO.getTaskType(), taskDTO.getRequirementName(),
                taskDTO.getDate(), taskDTO.getPlanFrom(), taskDTO.getPlanTo(),
                taskDTO.getAssign(), taskDTO.getReviewer());

        // Cap ID moi = ID task cuoi + 1 roi them vao cuoi danh sach
        lastId++;
        task.setId(lastId);
        taskList.add(task);

        return lastId;
    }

    // Xoa task theo ID; khong co ID do thi nem loi cho Controller bao lai (ham deleteTask cua de)
    public void deleteTask(int taskId) throws Exception {
        Task task = findById(taskId);

        // Khong tim thay task thi bao ID khong ton tai
        if (task == null) {
            throw new Exception(String.format(Message.ERROR_TASK_NOT_FOUND, taskId));
        }

        taskList.remove(task);
    }

    // Doi tung Task thanh 1 dong ResponseDTO de View in (ham getDataTasks cua de)
    public List<ResponseDTO> getDataTasks() {
        List<ResponseDTO> responseList = new ArrayList<>();

        // Duyet tung task (da tang dan theo ID vi luon them vao cuoi)
        for (Task task : taskList) {
            ResponseDTO responseDTO = new ResponseDTO();

            // Chep du lieu task sang dong bang; Time = To - From
            responseDTO.setId(task.getId());
            responseDTO.setRequirementName(task.getRequirementName());
            responseDTO.setTaskType(task.getTaskType());
            responseDTO.setDate(task.getDate());
            responseDTO.setTime(task.getPlanTo() - task.getPlanFrom());
            responseDTO.setAssign(task.getAssign());
            responseDTO.setReviewer(task.getReviewer());
            responseList.add(responseDTO);
        }

        return responseList;
    }

    // Kiem kho co rong khong
    public boolean isEmpty() {
        return taskList.isEmpty();
    }

    // Tim task theo ID; khong co thi tra null (chi dung trong kho)
    private Task findById(int taskId) {
        // Duyet tung task de so ID
        for (Task task : taskList) {
            // Trung ID thi tra ve task do
            if (task.getId() == taskId) {
                return task;
            }
        }

        return null;
    }
}

